// Epidemiology Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items. The MMWR area uses investigation-style scenarios and
// surveillance calculations like those in MMWR reports, not details of specific reports.
import {q, mix} from './q.js';
const CDC='CDC, Principles of Epidemiology in Public Health Practice', WHO='World Health Organization', MMWR='CDC, Morbidity and Mortality Weekly Report';
const INTRO='Introduction to Epidemiology', WORLD='World and Government Response to Infectious Diseases', MW='CDC: Morbidity and Mortality Weekly Report';

export default {
 id:'epidemiology-1',
 event:'Epidemiology',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'CDC Principles of Epidemiology (PH 101), WHO materials and CDC’s Morbidity and Mortality Weekly Report',
 plan:[{area:INTRO,weight:30},{area:WORLD,weight:20},{area:MW,weight:50}],
 questions:mix([
  q(INTRO,'Which definition best describes epidemiology?','Study of disease patterns and causes in populations',['The treatment of individual patients','The study of microorganisms and their genes only','The laboratory testing of blood'],'B','Epidemiology studies who gets sick, where and when (distribution) and why (determinants), and applies that knowledge to control health problems.',CDC),
  q(INTRO,'How does incidence differ from prevalence?','Incidence counts new cases; prevalence counts all existing cases',['Incidence counts all cases; prevalence counts new cases','They are the same measure','Incidence counts deaths only'],'D','Incidence measures risk of developing disease over a period. Prevalence measures how much disease exists at a point or period in time.',CDC),
  q(INTRO,'In a town of 10,000 people at risk, 50 new cases of a disease occur in one year. What is the incidence rate?','5 per 1,000 per year',['50 per 1,000 per year','0.5 per 1,000 per year','500 per 1,000 per year'],'A','New cases ÷ population at risk = 50 ÷ 10,000 = 0.005, which is 5 per 1,000 people per year.',CDC),
  q(INTRO,'Why can a chronic disease have a high prevalence even when its incidence is low?','It lasts a long time',['It is always contagious','It has a short duration','It is quickly cured'],'C','Prevalence ≈ incidence × duration. Long-lasting conditions accumulate in a population.',CDC),
  q(INTRO,'At a banquet, 30 of the 120 attendees became ill. What is the attack rate?','25%',['4%','30%','120%'],'B','Attack rate = ill ÷ people at risk × 100 = 30 ÷ 120 × 100 = 25%. Attack rates are used in outbreaks with a short exposure period.',CDC),
  q(INTRO,'Of 200 people diagnosed with a disease, 8 die from it. What is the case-fatality rate?','4%',['0.4%','8%','25%'],'D','Case-fatality rate = deaths ÷ cases × 100 = 8 ÷ 200 × 100 = 4%. It measures the severity of a disease.',CDC),
  q(INTRO,'Researchers follow smokers and nonsmokers over 20 years to compare how many develop lung cancer. What study design is this?','Cohort study',['Case-control study','Cross-sectional study','Ecological study'],'A','Cohort studies start with exposure groups and follow them forward to compare disease occurrence; they calculate relative risk.',CDC),
  q(INTRO,'Researchers compare people with a rare cancer to similar people without it, asking about past exposures. Which measure of association do they calculate?','Odds ratio',['Relative risk','Attack rate','Prevalence'],'C','Case-control studies start with disease status and look back at exposures. They are efficient for rare diseases and report odds ratios.',CDC),
  q(INTRO,'Among 100 exposed people, 20 became ill; among 100 unexposed people, 5 became ill. What is the relative risk?','4.0',['0.25','15','25'],'B','Relative risk = (20/100) ÷ (5/100) = 0.20 ÷ 0.05 = 4.0. The exposed group was four times as likely to become ill.',CDC),
  q(INTRO,'Which study design provides the strongest evidence that an intervention causes an outcome?','Randomized controlled trial',['Case report','Ecological study','Cross-sectional survey'],'D','Random assignment balances known and unknown factors between groups, reducing confounding.',CDC),
  q(INTRO,'Which of the Bradford Hill criteria is essential for showing that an exposure caused a disease?','Temporality',['Analogy to other diseases','The disease is common','The exposure is expensive'],'A','A cause must come before its effect. Other criteria, such as strength, consistency and dose-response, add support but are not all required.',CDC),
  q(INTRO,'A study finds coffee drinkers have more lung cancer, but coffee drinkers in the study also smoke more. What is smoking in this situation?','A confounder',['An outcome','A bias in measurement','An effect modifier only'],'C','A confounder is linked to both the exposure and the outcome and can create a false association. Studies adjust for confounders.',CDC),
  q(INTRO,'A health department relies on doctors to report cases on their own. What type of surveillance is this?','Passive surveillance',['Active surveillance','Sentinel surveillance','Syndromic surveillance'],'B','Passive surveillance is inexpensive but often incomplete. Active surveillance means the health department reaches out to find cases.',CDC),
  q(INTRO,'A disease that spreads worldwide across many countries and continents is called:','A pandemic',['Endemic','Sporadic','An outbreak in one school'],'D','Endemic means constantly present at a usual level; an epidemic is an increase above expected; a pandemic spreads across countries or continents.',CDC),
  q(INTRO,'A disease has a basic reproduction number (R₀) of 4. About what proportion of the population must be immune to stop sustained spread?','75%',['25%','40%','100%'],'A','Herd immunity threshold ≈ 1 − 1/R₀ = 1 − 1/4 = 0.75, or 75%. More contagious diseases, such as measles, need much higher coverage.',CDC),
  q(WORLD,'Under the International Health Regulations, which organization can declare a Public Health Emergency of International Concern?','World Health Organization',['United Nations Security Council','CDC','World Bank'],'C','The WHO Director-General declares a PHEIC, which triggers coordinated global recommendations.',WHO),
  q(WORLD,'The CDC is part of which federal department?','Department of Health and Human Services',['Department of Defense','Department of Agriculture','Department of Homeland Security'],'B','The CDC is an operating division of HHS, alongside agencies such as the FDA and NIH.',CDC),
  q(WORLD,'In the United States, to whom do healthcare providers and labs first report notifiable diseases?','State or local health departments',['The World Health Organization','The patient’s employer','The hospital’s insurance company'],'D','Reporting requirements are set by states. States then share data voluntarily with the CDC through the National Notifiable Diseases Surveillance System.',CDC),
  q(WORLD,'How does quarantine differ from isolation?','Quarantine: exposed people; isolation: sick people',['Quarantine: sick people; isolation: exposed people','They mean exactly the same thing','Isolation applies only to animals'],'A','Isolation keeps infected people away from others. Quarantine restricts movement of people who may have been exposed until it is clear they are not infected.',CDC),
  q(WORLD,'What is the purpose of contact tracing?','Finding and notifying exposed people',['Tracking hospital bed availability','Following vaccine shipments','Locating sources of funding'],'C','Contacts can be tested, quarantined or treated early, interrupting chains of transmission.',CDC),
  q(WORLD,'Which disease was declared eradicated worldwide by the WHO in 1980?','Smallpox',['Polio','Measles','Tuberculosis'],'B','Smallpox eradication succeeded through vaccination, surveillance and ring vaccination. It remains the only human disease eradicated.',WHO),
  q(WORLD,'Wild poliovirus transmission continues in which two countries?','Pakistan and Afghanistan',['Brazil and Mexico','India and China','Canada and the United States'],'D','The Global Polio Eradication Initiative has eliminated wild poliovirus from most of the world; transmission persists in these two countries.',WHO),
  q(WORLD,'What is the CDC’s Epidemic Intelligence Service (EIS)?','A program training “disease detectives”',['A spy agency for foreign governments','A federal vaccine manufacturer','A hospital accreditation group'],'A','EIS officers investigate outbreaks and health threats in the United States and around the world.',CDC),
  q(WORLD,'What is the Strategic National Stockpile?','A national emergency supply of medicines',['A database of disease cases','A list of all FDA-approved vaccines','A program that pays for flu shots'],'C','The stockpile provides vaccines, antidotes, ventilators and other supplies when local resources are overwhelmed.',CDC),
  q(WORLD,'Which approach recognizes that human, animal and environmental health are connected?','One Health',['Herd immunity','Universal precautions','Primary prevention only'],'B','Many emerging infections are zoonotic. One Health coordinates human medicine, veterinary medicine and environmental science.',CDC),
  q(MW,'How often is the Morbidity and Mortality Weekly Report published?','Weekly',['Daily','Monthly','Once a year'],'D','MMWR is the CDC’s main publication for timely public health information and recommendations, including outbreak reports and surveillance summaries.',MMWR),
  q(MW,'In a field investigation, after preparing for fieldwork, what is the next step?','Establish that an outbreak exists',['Implement control measures only','Write the final report','Start a randomized trial'],'A','Investigators compare the observed number of cases with the expected number to confirm an outbreak, then verify the diagnosis.',CDC),
  q(MW,'Which elements make up a case definition in an outbreak investigation?','Clinical criteria with person, place, time',['Only laboratory results','Only the number of deaths reported','The cost of treatment'],'C','A clear case definition ensures cases are counted consistently. It may be broad at first and narrowed later.',CDC),
  q(MW,'A case meets the clinical criteria and is epidemiologically linked to a lab-confirmed case but has no lab test. How is it usually classified?','Probable case',['Confirmed case','Excluded case','Suspected outbreak'],'B','Confirmed cases have laboratory confirmation. Probable cases meet clinical criteria with an epidemiologic link or other supporting evidence.',CDC),
  q(MW,'An epidemic curve shows cases rising sharply and falling within about one incubation period. What type of outbreak does this suggest?','Point-source outbreak',['Propagated outbreak','Continuous common-source outbreak','Endemic disease'],'D','A single brief exposure, such as one contaminated meal, produces a tight cluster of cases.',CDC),
  q(MW,'An epidemic curve shows a series of progressively taller peaks about one incubation period apart. What does this indicate?','Person-to-person spread',['A single contaminated meal','A data entry error','A seasonal allergy pattern'],'A','Each generation of cases infects the next, producing successive waves typical of measles or influenza.',CDC),
  q(MW,'In a point-source outbreak, how can investigators estimate the likely incubation period?','By timing exposure to symptom onset',['By counting the total number of cases','By measuring the size of the outbreak area','By counting available hospital beds'],'C','The median time from exposure to onset suggests the incubation period, which helps identify the likely agent.',CDC),
  q(MW,'At a picnic, 40 of 50 people who ate chicken salad became ill, versus 5 of 50 who did not. What is the risk ratio?','8',['4','35','0.125'],'B','Attack rate among those who ate it = 80%; among those who did not = 10%. 80 ÷ 10 = 8, strongly implicating the chicken salad.',CDC),
  q(MW,'What is a line list in an outbreak investigation?','A table with one row per case',['A map of case locations','A graph of cases over time','A list of all hospital staff involved'],'D','Line lists organize variables such as age, sex, onset date and exposures, making patterns easier to spot.',CDC),
  q(MW,'What does a spot map show investigators?','Where cases live or were exposed',['How many cases occurred each day','The cost of the outbreak','The age of each case'],'A','Clusters on a spot map can point to a common source, as in John Snow’s classic cholera map.',CDC),
  q(MW,'Early in an outbreak, investigators interview a few cases in depth about everything they ate and did. What is the purpose?','To generate hypotheses about the source',['To prove the cause statistically','To issue a final report','To calculate the case-fatality rate'],'C','Open-ended interviews generate hypotheses. Analytic studies, such as case-control studies, then test them.',CDC),
  q(MW,'Should control measures wait until an outbreak investigation is complete?','No; act once evidence is sufficient',['Yes, always wait for final results','Yes, until the final report is published','No, control measures are never used'],'B','Public health action is often taken early, such as recalling a suspect food, while the investigation continues.',CDC),
  q(MW,'A surveillance summary reports 250 cases in a state of 5 million people. What is the rate per 100,000?','5 per 100,000',['0.5 per 100,000','50 per 100,000','250 per 100,000'],'D','Rate = cases ÷ population × 100,000 = 250 ÷ 5,000,000 × 100,000 = 5 per 100,000. Rates allow fair comparison between places of different sizes.',MMWR),
  q(MW,'Why do surveillance reports often present age-adjusted rates?','To compare populations fairly',['To make rates look higher','To remove all cases among children','Because raw counts are always wrong'],'A','An older population naturally has more chronic disease. Age adjustment removes that difference so rates can be compared.',MMWR),
  q(MW,'Why do reported case counts usually underestimate the true number of infections?','Many mild cases are never tested',['Doctors report every case twice','Labs test everyone in the population','Surveillance counts only deaths'],'C','Only a fraction of infections are diagnosed and reported, so surveillance data show trends rather than exact totals.',MMWR),
  q(MW,'Tracking emergency department visits for “flu-like illness” before diagnoses are confirmed is an example of:','Syndromic surveillance',['Passive case reporting','A randomized trial','Contact tracing'],'B','Syndromic surveillance uses early data, such as symptoms, to detect outbreaks quickly.',MMWR),
  q(MW,'Why has wastewater surveillance become useful for monitoring infections such as COVID-19?','It tracks virus shed by a whole community',['It identifies each infected person by name','It replaces all clinical testing','It measures only drinking water quality'],'D','Many infected people shed virus in stool, even without symptoms. Trends in sewage can signal rising infections early.',MMWR),
  q(MW,'Whose vaccine recommendations are published in MMWR once adopted by the CDC?','ACIP',['The World Bank’s health office','The Food and Agriculture Organization','State medical boards'],'A','ACIP reviews evidence and recommends how vaccines should be used in the United States.',MMWR),
  q(MW,'An outbreak of Legionnaires’ disease is investigated. Which environmental source is commonly implicated?','Cooling towers',['Undercooked raw chicken','Mosquito bites','Person-to-person coughing'],'C','Legionella grows in warm water and spreads through inhaled mist, such as from cooling towers, hot tubs and decorative fountains.',MMWR),
  q(MW,'Why are measles outbreaks typically concentrated among unvaccinated people?','It is very contagious and the vaccine works well',['Measles affects only adults','Measles spreads only through food','Measles has no effective vaccine yet'],'B','Measles has an R₀ of about 12–18. Two doses of MMR are about 97% effective, so outbreaks occur mostly among the unvaccinated.',MMWR),
  q(MW,'Which pathogen is the leading cause of foodborne illness in the United States?','Norovirus',['Salmonella','Botulism','Listeria'],'D','Norovirus causes the most foodborne illnesses, often spread by infected food handlers. Salmonella is a leading cause of hospitalization and death.',MMWR),
  q(MW,'In West Nile virus transmission, what role do mosquitoes play?','Vector',['Vehicle','Reservoir only','Host with no role in spread'],'A','A vector is a living organism, often an insect, that carries an agent to a host. A vehicle is a nonliving object, such as food or water.',CDC),
  q(MW,'In a household study, 6 of 30 susceptible contacts became ill after exposure to a primary case. What is the secondary attack rate?','20%',['5%','6%','30%'],'C','Secondary attack rate = new cases among contacts ÷ susceptible contacts × 100 = 6 ÷ 30 × 100 = 20%.',CDC),
  q(MW,'In MMWR reports, what is the purpose of the “What is already known?” summary box?','To summarize prior knowledge',['To list the authors’ names','To give the publication cost and fees','To list all references'],'B','MMWR summaries state what is already known, what the report adds, and the implications for public health practice.',MMWR),
  q(MW,'After an outbreak investigation identifies the source, which step communicates the findings?','Reporting to public health partners',['Destroying the data','Waiting several years to release results','Only telling the cases'],'D','Communicating findings informs prevention and policy. Reports, presentations and MMWR articles share lessons learned.',CDC)
 ],163)
};
